// Черновая разметка сериалов (трек Е2, ROADMAP §8) — тем же способом, что фильмы (draftAnnotations.ts):
// черновик модели по знанию сериала, без просмотра, статус needs_review — кандидаты для кураторской.
// Единица — сериал целиком. У антологии («Настоящий детектив», «Фарго», «Чёрное зеркало») единица —
// сезон: каждый сезон размечен отдельно, а разметка сериала — общая рамка. У обычного сериала сезон
// размечается только там, где он заметно другой (поправка). Эпизоды не размечаем.
// Отбор (30.09): сериалы из присланных профилей (109) и из справочника (разметка по таблице, полки) —
// 160; размечено то, о чём у модели достаточно знаний. Не размечены — малоизвестное, где черновик был
// бы выдумкой (список — HANDOFF «Разметка сериалов»).
// Ключ — `imdb:<id>`: номера TMDb у сериалов свои и пересекаются с фильмами.
// Шкала та же, что у фильмов: детское 1, массовое развлечение 2–3, умное массовое 4, авторское с
// доступным входом 5–6, сложная форма 6–7, медленное авторское 7–8. Длина сериала — не уровень:
// общее время — отдельный барьер подбора (Е4, из `series` карточки).
import type { AnnotationProvider, AnnotationStatus, CognitiveOperation, Confidence, ISODate } from '@/types/tmdf';
import type { FirstPassAnnotation } from './userAnnotations';

export const seriesAnnotationMeta: { provider: AnnotationProvider; model: string; status: AnnotationStatus; createdAt: ISODate; tmdfVersion: string } = {
  provider: 'anthropic_api', model: 'claude-opus-5-5', status: 'needs_review', createdAt: '2026-09-30', tmdfVersion: '0.3.1',
};

/** Сезон: у антологии — самостоятельная единица, у обычного сериала — поправка к общей разметке. */
export interface SeasonDraft extends FirstPassAnnotation { year?: number }
export interface SeriesDraft extends FirstPassAnnotation {
  /** сезоны — отдельные истории; разметка сериала — общая рамка, единица подбора — сезон */
  anthology?: boolean;
  seasons?: Record<number, SeasonDraft>;
}

const a = (
  ops: [CognitiveOperation, number][], level: number, barriers: string[], warnings: string[], niche: boolean,
  confidence: Confidence, what: string,
): SeriesDraft => ({ ops, level, barriers, warnings, niche, confidence, what });
const s = (year: number, d: FirstPassAnnotation): SeasonDraft => ({ year, ...d });
const anthology = (d: SeriesDraft, seasons: Record<number, SeasonDraft>): SeriesDraft => ({ ...d, anthology: true, seasons });
const withSeasons = (d: SeriesDraft, seasons: Record<number, SeasonDraft>): SeriesDraft => ({ ...d, seasons });

