/** Разметка сезона: у антологии — сезон как самостоятельная единица, у обычного сериала — поправка
 *  сезона, если есть, иначе разметка сериала. */
export function seasonDraft(d: SeriesDraft, season: number): FirstPassAnnotation {
  return d.seasons?.[season] ?? d;
}
